from urllib.parse import urlsplit, urlunsplit, parse_qsl


def _replace_host_preserving_port(parts, new_host):
    """ホスト名だけを置き換え、ユーザー情報とポートは維持する。"""
    netloc = parts.netloc

    if "@" in netloc:
        userinfo, hostport = netloc.rsplit("@", 1)
        userinfo += "@"
    else:
        userinfo = ""
        hostport = netloc

    port = ""

    # IPv6 アドレスの場合
    if hostport.startswith("["):
        closing = hostport.find("]")
        if closing != -1:
            suffix = hostport[closing + 1:]
            if suffix.startswith(":"):
                port = suffix
    # 通常の hostname:port の場合
    elif hostport.count(":") == 1:
        _, possible_port = hostport.rsplit(":", 1)
        port = ":" + possible_port

    # new_host が IPv6 アドレスなら角括弧で囲む
    if ":" in new_host and not (
        new_host.startswith("[") and new_host.endswith("]")
    ):
        new_host = f"[{new_host}]"

    new_netloc = f"{userinfo}{new_host}{port}"
    return parts._replace(netloc=new_netloc)


def apply_rewrite_rules(rules, urls):
    """
    rules の順序に従って各 URL に最初に適合したルールを適用する。

    適合したルールの action が "block" の場合は None を返す。
    """
    valid_match_types = {"path_prefix", "host", "query_param"}
    valid_actions = {
        "strip_prefix",
        "redirect_host",
        "add_query_param",
        "block",
    }

    results = []

    for url in urls:
        parts = urlsplit(url)
        matched = False
        result = url

        for rule in rules:
            match_type = rule["match_type"]
            match_value = rule["match_value"]
            action = rule["action"]

            if match_type not in valid_match_types:
                raise ValueError(f"Unknown match_type: {match_type}")
            if action not in valid_actions:
                raise ValueError(f"Unknown action: {action}")
            if action != "block" and "action_value" not in rule:
                raise ValueError(
                    f"action_value is required for action={action!r}"
                )

            host = parts.hostname or ""
            host_lower = host.lower()
            match_lower = str(match_value).lower()

            is_match = False

            if match_type == "path_prefix":
                is_match = parts.path.startswith(str(match_value))

            elif match_type == "host":
                if match_lower.startswith("*."):
                    suffix = match_lower[2:]
                    # ドメインそのものは除外し、厳密なサブドメインだけを許可
                    is_match = (
                        host_lower.endswith("." + suffix)
                        and host_lower != suffix
                    )
                else:
                    is_match = host_lower == match_lower

            elif match_type == "query_param":
                query_names = {
                    name for name, _ in parse_qsl(
                        parts.query,
                        keep_blank_values=True,
                    )
                }
                is_match = str(match_value) in query_names

            if not is_match:
                continue

            # 最初に適合したルールだけを使う
            matched = True

            if action == "block":
                result = None

            elif action == "strip_prefix":
                prefix = str(rule["action_value"])
                new_path = parts.path

                if new_path.startswith(prefix):
                    new_path = new_path[len(prefix):]

                if new_path == "":
                    new_path = "/"

                result = urlunsplit(parts._replace(path=new_path))

            elif action == "redirect_host":
                new_parts = _replace_host_preserving_port(
                    parts,
                    str(rule["action_value"]),
                )
                result = urlunsplit(new_parts)

            elif action == "add_query_param":
                addition = str(rule["action_value"])
                new_query = (
                    addition
                    if not parts.query
                    else f"{parts.query}&{addition}"
                )
                result = urlunsplit(parts._replace(query=new_query))

            break

        # どのルールにも適合しなければ元の URL をそのまま返す
        results.append(result if matched else url)

    return results
